// Cloudflare Worker entry. OpenNext generates `.open-next/worker.js`; this
// wrapper logs each request that reaches the Worker. Static files are served
// by the assets binding and do not enter this fetch handler.
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import openNextWorker from './.open-next/worker.js'

interface OpenNextWorker {
  fetch(
    request: Request,
    env: CloudflareEnv,
    context: ExecutionContext,
  ): Promise<Response>
}

const openNext = openNextWorker as OpenNextWorker

function pathnameFromRequest(request: Request): string {
  return new URL(request.url).pathname
}

function errorMessageFromUnknown(error: unknown): string {
  if (error instanceof Error) {
    return error.message
  }
  return String(error)
}

export default {
  async fetch(
    request: Request,
    env: CloudflareEnv,
    context: ExecutionContext,
  ): Promise<Response> {
    const startedAt = Date.now()
    const method = request.method
    const path = pathnameFromRequest(request)

    try {
      const response = await openNext.fetch(request, env, context)
      console.log({
        message: 'request',
        method,
        path,
        status: response.status,
        latencyMs: Date.now() - startedAt,
      })
      return response
    } catch (error) {
      console.error({
        message: 'request failed',
        method,
        path,
        error: errorMessageFromUnknown(error),
        latencyMs: Date.now() - startedAt,
      })
      throw error
    }
  },
}
